import json,collections,sys
from pathlib import Path
import numpy as np
R=Path('/Volumes/UFO-Work/field/research-v1');d=json.loads((R/'development.json').read_text());rows=d['samples'];y=np.array([r['label']=='anomalous' for r in rows]);g=np.array([r['group'] for r in rows]);groups=np.unique(g);results=json.loads((R/'ablation-results.json').read_text());rng=np.random.default_rng(411);draws=rng.integers(0,len(groups),size=(2000,len(groups)));summaries=[]
# Paired resampling of entire original recording groups (never independent frames).
for r in results['results']:
 z=np.load(R/(r['name']+'.npz'));pred=z['decision'];prob=z['prob'];valid=np.isfinite(prob);counts=np.array([[sum(valid&(g==group)&y&pred),sum(valid&(g==group)&~y&pred),sum(valid&(g==group)&~y&~pred),sum(valid&(g==group)&y&~pred)] for group in groups]);b=counts[draws].sum(1);tp,fp,tn,fn=b.T
 metrics={'recall':np.divide(tp,tp+fn,out=np.full(len(tp),np.nan),where=(tp+fn)>0),'false_positive_rate':np.divide(fp,fp+tn,out=np.full(len(tp),np.nan),where=(fp+tn)>0),'precision':np.divide(tp,tp+fp,out=np.full(len(tp),np.nan),where=(tp+fp)>0)}
 summaries.append(dict(name=r['name'],confidence_intervals={k:list(np.nanquantile(v,[.025,.975])) for k,v in metrics.items()}))
(R/'ablation-uncertainty.json').write_text(json.dumps(dict(method='2000 paired recording-cluster bootstrap replicates; historical development selection, not independent confirmatory inference',recordings=len(groups),runs=summaries),indent=2))
grouped=collections.defaultdict(list)
for r in results['results']:grouped[(r['backbone'],r['head'],r['balance'])].append(r['metrics'])
lines=['# Model research — 2026-11-14','','## Decision','','Keep the current deployed MobileNet nonlinear model. DINOv2 is a useful challenger, not an across-the-board upgrade. Do not promote on these historical results.','','## Controlled experiment','','6,175 selected reviewed RGB crops: all 1,168 positives and at most 40 negatives per recording. Both backbones see identical images. Five recording/pixel-linked folds rotate through three fitting folds, one threshold-selection fold, and one evaluation fold. Thresholds target 90% calibration recall. Three seeds per recipe; deterministic linear fits repeat identically and are not three independent observations.','','These are historical development results on a sampled population. They are neither live error rates nor untouched test accuracy. Reusing old recordings and choosing a recipe after seeing this table limits inferential claims.','','| Backbone | Head | Weighting | FP rate | Recall | Precision | Accuracy | AP |','|---|---|---|---:|---:|---:|---:|---:|']
for k,values in grouped.items():lines.append('| '+' | '.join(k)+' | '+' | '.join(f'{np.mean([v[m] for v in values])*100:.2f}%' for m in ['false_positive_rate','recall','precision','accuracy','average_precision'])+' |')
lines+=['','Lower FP alone is insufficient: DINOv2 nonlinear improves FP but loses recall against MobileNet nonlinear. Calibration thresholds also vary sharply by recording fold, indicating distribution shift. The published JSON includes raw confusion counts, Brier scores, calibration error, fold thresholds and group-bootstrap uncertainty.','','## Prospective protocol','','All historical manifests are registered as exposed. New recording groups are assigned label-blind: 20% reserved, 80% eligible for development. Exact-pixel and recording links connect partitions. A connection between already reserved and exposed evidence quarantines the connected component; it cannot be called an independent test. Missing provenance is withheld from fitting. Source images and human labels are preserved. All four trainers enforce the same registry.','','A continuously running original generation remains development data. Truly new recording groups are required; renaming old data does not make it independent. Holdout scoring must also establish original capture time after the protocol boundary before being described as prospective. No such fresh reviewed cohort exists yet.','','## Event and temporal evidence','','The read-only observer measures contiguous processed-frame intervals and motion-track summaries. Gaps remain unobserved, not assumed healthy. It records no video and cannot suppress a detection or activate a model. Temporal features remain descriptive until qualified against independent event truth.','','False alerts per camera-hour requires complete alert review over measured coverage. Event recall also needs an independent missed-event audit; reviewing only detections cannot measure objects never proposed. These values remain null until those conditions are met, rather than showing a fabricated zero.','','## Remaining evidence requirements','','1. Fresh independent recordings with positive and negative human-reviewed events, spanning day and night.','2. An independent audit of sampled continuous footage to establish missed events and proposal-stage recall.','3. Freeze each challenger artifact, preprocessing, decision settings and evaluation protocol before opening the confirmatory cohort.','4. Compare paired recording/event outcomes with uncertainty; retain runtime/export parity and sustained-load checks before any live replacement.','','These are external evidence requirements, not claims that a more complex model has already solved detection. The current manual Train now activation rule remains unchanged.']
(R/'RESEARCH-REPORT.md').write_text('\n'.join(lines)+'\n');print('report and uncertainty saved')
